head.b:skin:

/* --- MODERN VARIABLES --- */
:root {
    --primary: #E60000; /* Richer Red */
    --primary-dark: #B30000;
    --secondary: #1A1A1A;
    --bg-body: #F8F9FA;
    --bg-card: #FFFFFF;
    --text-main: #121212;
    --text-muted: #555555;
    --border: #E5E5E5;
    --shadow-hover: 0 10px 30px rgba(0,0,0,0.12);
    --shadow-card: 0 4px 6px rgba(0,0,0,0.04);
    --radius: 12px;
    --font-head: 'Playfair Display', serif; /* Editorial Font */
    --font-body: 'Outfit', sans-serif; /* Modern Clean Font */
    --transition: all 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    --footer-bg: #0f0f0f;
}

/* --- BASE --- */
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family: var(--font-body); background: var(--bg-body); color: var(--text-main); line-height: 1.6; -webkit-font-smoothing: antialiased; }
a { text-decoration: none; color: inherit; cursor: pointer; transition: var(--transition); }
ul { list-style: none; }
.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }

/* --- ANIMATIONS --- */
@keyframes fadeInUp {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}
@keyframes shimmer {
    0% { background-position: -200% 0; }
    100% { background-position: 200% 0; }
}
.animate-in { animation: fadeInUp 0.6s ease forwards; opacity: 0; } 
.delay-1 { animation-delay: 0.1s; }
.delay-2 { animation-delay: 0.2s; }
.delay-3 { animation-delay: 0.3s; }

/* --- HEADER --- */
.top-bar { background: #000; color: #fff; padding: 8px 0; font-size: 0.8rem; letter-spacing: 0.5px; }
.top-bar .container { display: flex; justify-content: space-between; align-items: center; }
.top-bar a { opacity: 0.8; transition: 0.3s; }
.top-bar a:hover { opacity: 1; color: var(--primary); }

.main-header { background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); position: sticky; top: 0; z-index: 1000; box-shadow: 0 2px 20px rgba(0,0,0,0.05); border-bottom: 2px solid var(--primary); }
.header-content { height: 80px; display: flex; justify-content: space-between; align-items: center; }

.logo { display: flex; align-items: center; gap: 5px; font-weight: 800; font-size: 1.8rem; letter-spacing: -1px; }
.logo span.ai { background: var(--secondary); color: #fff; padding: 2px 8px; border-radius: 6px; }
.logo span.news { color: var(--primary); }

/* Navigation */
.nav-links { display: flex; gap: 30px; }
.nav-links a { font-weight: 600; font-size: 0.95rem; text-transform: uppercase; letter-spacing: 0.5px; position: relative; color: var(--text-main); }
.nav-links a::after { content: ''; position: absolute; bottom: -5px; left: 0; width: 0; height: 2px; background: var(--primary); transition: var(--transition); }
.nav-links a:hover::after, .nav-links a.active::after { width: 100%; }

/* Header Social Icons */
.header-social { display: flex; gap: 15px; align-items: center; }
.header-social a { width: 32px; height: 32px; border-radius: 50%; background: #f0f0f0; display: flex; align-items: center; justify-content: center; color: var(--secondary); transition: 0.3s; font-size: 0.9rem; }
.header-social a:hover { background: var(--primary); color: #fff; transform: translateY(-3px); }

/* Mobile Menu */
.mobile-only { display: none; }
.mobile-btn { font-size: 1.5rem; background: none; border: none; cursor: pointer; color: var(--text-main); }

/* --- TICKER --- */
.ticker-wrap { background: var(--secondary); color: #fff; height: 40px; overflow: hidden; display: flex; font-weight: 500; }
.ticker-title { background: var(--primary); padding: 0 25px; display: flex; align-items: center; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; font-size: 0.85rem; z-index: 5; position: relative; }
.ticker-title::after { content:''; position: absolute; right: -20px; top: 0; border-top: 40px solid var(--primary); border-right: 20px solid transparent; }
.ticker-content { display: flex; align-items: center; padding-left: 20px; animation: ticker 25s linear infinite; white-space: nowrap; }
.ticker-item { margin-right: 50px; font-size: 0.9rem; opacity: 0.9; }
@keyframes ticker { 0% { transform: translateX(0); } 100% { transform: translateX(-100%); } }

/* --- HERO SLIDER --- */
.hero-section { margin: 30px 0; border-radius: var(--radius); overflow: hidden; position: relative; height: 500px; box-shadow: var(--shadow-card); }
.hero-slider { position: relative; width: 100%; height: 100%; }
.hero-slide { position: absolute; top: 0; left: 0; width: 100%; height: 100%; opacity: 0; transition: opacity 0.8s ease-in-out; z-index: 1; pointer-events: none; }
.hero-slide.active { opacity: 1; z-index: 2; pointer-events: auto; }

.hero-img { width: 100%; height: 100%; object-fit: cover; transition: transform 6s ease; }
.hero-slide.active .hero-img { transform: scale(1.1); } /* Zoom effect on active */

.hero-overlay { position: absolute; bottom: 0; left: 0; right: 0; background: linear-gradient(0deg, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.5) 50%, transparent 100%); padding: 60px 40px; color: #fff; display: flex; flex-direction: column; justify-content: flex-end; z-index: 3; }

.tag { background: var(--primary); color: #fff; padding: 5px 12px; font-size: 0.75rem; font-weight: 700; text-transform: uppercase; border-radius: 4px; align-self: flex-start; margin-bottom: 15px; letter-spacing: 1px; }
.hero-title { font-family: var(--font-head); font-size: 3rem; line-height: 1.1; margin-bottom: 10px; width: 80%; text-shadow: 0 2px 10px rgba(0,0,0,0.3); }
.hero-meta { opacity: 0.8; font-size: 0.9rem; }

/* Slider Controls */
.slider-btn { position: absolute; top: 50%; transform: translateY(-50%); background: rgba(0,0,0,0.5); color: white; border: none; font-size: 2rem; padding: 10px 15px; cursor: pointer; z-index: 10; border-radius: 50%; width: 50px; height: 50px; display: flex; align-items: center; justify-content: center; transition: 0.3s; }
.slider-btn:hover { background: var(--primary); }
.prev-btn { left: 20px; }
.next-btn { right: 20px; }

.slider-dots { position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%); display: flex; gap: 10px; z-index: 10; }
.dot { width: 12px; height: 12px; background: rgba(255,255,255,0.5); border-radius: 50%; cursor: pointer; transition: 0.3s; }
.dot.active { background: var(--primary); transform: scale(1.2); }

/* --- GRID --- */
.content-grid { display: grid; grid-template-columns: 2.5fr 1fr; gap: 40px; margin-bottom: 60px; }
.section-head { display: flex; align-items: center; margin-bottom: 25px; border-bottom: 2px solid var(--border); padding-bottom: 10px; position: relative; }
.section-head::after { content: ''; position: absolute; bottom: -2px; left: 0; width: 80px; height: 2px; background: var(--primary); }
.section-head h2 { font-family: var(--font-head); font-size: 1.8rem; color: var(--secondary); margin-right: 20px; }

.news-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 30px; }
.news-card { background: var(--bg-card); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-card); transition: var(--transition); border: 1px solid transparent; display: flex; flex-direction: column; height: 100%; }
.news-card:hover { transform: translateY(-8px); box-shadow: var(--shadow-hover); border-color: rgba(0,0,0,0.05); }
.card-thumb { height: 220px; overflow: hidden; position: relative; }
.card-thumb img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.news-card:hover .card-thumb img { transform: scale(1.1); }
.card-body { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }
.card-tag { color: var(--primary); font-weight: 700; font-size: 0.8rem; text-transform: uppercase; margin-bottom: 10px; display: block; }
.card-title { font-family: var(--font-head); font-size: 1.4rem; line-height: 1.3; margin-bottom: 12px; color: var(--text-main); transition: 0.2s; }
.news-card:hover .card-title { color: var(--primary); }
.card-desc { font-size: 0.95rem; color: var(--text-muted); margin-bottom: 20px; flex-grow: 1; }
.card-footer { border-top: 1px solid var(--border); padding-top: 15px; font-size: 0.85rem; color: var(--text-light); display: flex; justify-content: space-between; }

/* SIDEBAR */
.widget { background: var(--bg-card); padding: 30px; border-radius: var(--radius); box-shadow: var(--shadow-card); margin-bottom: 30px; border: 1px solid var(--border); }
.widget h3 { font-family: var(--font-head); font-size: 1.4rem; margin-bottom: 20px; border-bottom: 1px solid var(--border); padding-bottom: 10px; }
.trending-item { display: flex; align-items: start; margin-bottom: 15px; padding-bottom: 15px; border-bottom: 1px solid #f0f0f0; }
.trending-rank { font-size: 2rem; font-weight: 800; color: #eee; line-height: 1; margin-right: 15px; font-family: var(--font-head); -webkit-text-stroke: 1px var(--text-light); }
.trending-info h4 { font-size: 1rem; font-weight: 600; line-height: 1.4; transition: 0.2s; }
.trending-item:hover h4 { color: var(--primary); }

/* SINGLE POST STYLES */
.post-wrapper { background: #fff; padding: 40px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.05); }
.post-header { margin-bottom: 30px; text-align: center; }
.post-title { font-family: var(--font-head); font-size: 2.5rem; line-height: 1.2; margin-bottom: 15px; }
.post-meta { color: #666; font-size: 0.9rem; text-transform: uppercase; letter-spacing: 1px; }
.post-body { font-size: 1.1rem; line-height: 1.8; color: #333; }
.post-body p { margin-bottom: 20px; }
.post-body img { max-width: 100%; height: auto; border-radius: 8px; margin: 20px 0; }
.post-body h2 { font-family: var(--font-head); margin-top: 30px; margin-bottom: 15px; font-size: 1.8rem; }
.post-body ul { list-style: disc; margin-left: 20px; margin-bottom: 20px; }
.post-body li { margin-bottom: 10px; }

/* FOOTER (PREMIUM REDESIGN) */
.main-footer { 
    background-color: var(--footer-bg); 
    color: #ddd; 
    padding: 80px 0 0; 
    margin-top: 80px; 
    border-top: 4px solid var(--primary);
    font-family: var(--font-body);
}
.footer-grid { 
    display: grid; 
    grid-template-columns: 2fr 1fr 1fr 1.5fr; 
    gap: 50px; 
    margin-bottom: 60px; 
}
.footer-col h3 { 
    font-family: var(--font-head); font-size: 1.3rem; margin-bottom: 25px; color: #fff; text-transform: uppercase; letter-spacing: 1px; 
}
.footer-desc { color: #888; margin-bottom: 25px; line-height: 1.7; font-size: 0.95rem; }

.footer-social-new { display: flex; gap: 10px; }
.footer-social-new a { 
    width: 40px; height: 40px; background: #222; border-radius: 50%; color: #fff; 
    display: flex; align-items: center; justify-content: center; transition: 0.3s; 
}
.footer-social-new a:hover { background: var(--primary); transform: translateY(-5px); box-shadow: 0 5px 15px rgba(230,0,0,0.3); }

.footer-links li { margin-bottom: 12px; }
.footer-links a { color: #aaa; transition: 0.3s; display: inline-block; font-size: 0.95rem; }
.footer-links a:hover { color: var(--primary); padding-left: 5px; }

.footer-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.footer-tag { 
    background: #222; color: #ccc; padding: 6px 12px; font-size: 0.8rem; border-radius: 20px; transition: 0.3s; 
}
.footer-tag:hover { background: var(--primary); color: #fff; }

.newsletter-box { background: #151515; padding: 20px; border-radius: 8px; border: 1px solid #333; }
.newsletter-input { 
    width: 100%; padding: 12px; background: #000; border: 1px solid #444; color: #fff; border-radius: 4px; margin-bottom: 10px; outline: none; 
}
.newsletter-input:focus { border-color: var(--primary); }
.newsletter-btn { 
    width: 100%; background: var(--primary); color: #fff; padding: 12px; border: none; border-radius: 4px; font-weight: 600; cursor: pointer; transition: 0.3s; 
}
.newsletter-btn:hover { background: var(--primary-dark); }

.footer-bottom { 
    background: #000; padding: 25px 0; border-top: 1px solid #222; text-align: center; color: #666; font-size: 0.85rem; 
    display: flex; justify-content: space-between; align-items: center;
}
.footer-bottom-links a { color: #666; margin-left: 20px; }
.footer-bottom-links a:hover { color: #fff; }

/* SKELETON */
.skeleton { background: #e0e0e0; background: linear-gradient(90deg, #e0e0e0 0%, #f0f0f0 50%, #e0e0e0 100%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 6px; }

/* RESPONSIVE */
@media (max-width: 900px) {
    .footer-grid { grid-template-columns: 1fr 1fr; }
    .nav-links, .header-social { display: none; } /* Hide Desktop Nav & Icons */
    .mobile-only { display: block; } /* Show Hamburger */
    .footer-bottom { flex-direction: column; gap: 10px; }
}
@media (max-width: 768px) {
    .content-grid, .news-grid { grid-template-columns: 1fr; }
    .hero-section { height: 350px; }
    .hero-title { font-size: 2rem; width: 100%; }
    .footer-grid { grid-template-columns: 1fr; gap: 40px; }
}

div.script:
// Global scope for TTS
var currentUtterance = null;

function toggleAudio(btn) {
    const icon = btn.querySelector('i');
    const postWrapper = btn.closest('.post-wrapper');
    const text = postWrapper.querySelector('.post-body').innerText;

    // 1. Stop if currently speaking
    if (window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
        // Reset all buttons
        document.querySelectorAll('.audio-btn').forEach(b => {
            b.style.background = "#222";
            b.innerHTML = ' Listen to News';
        });

        // If we clicked the SAME button that was playing, just stop.
        // If we clicked a DIFFERENT button, start new audio.
        if (btn.classList.contains('playing')) {
            btn.classList.remove('playing');
            return;
        }
    }

    // 2. Start New Audio
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    utterance.rate = 1.0;

    utterance.onend = function() {
        btn.style.background = "#222";
        btn.innerHTML = ' Listen to News';
        btn.classList.remove('playing');
    };

    window.speechSynthesis.speak(utterance);
    btn.style.background = "#E60000"; // Active Red
    btn.innerHTML = ' Stop Audio';
    btn.classList.add('playing');
}

